import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import "./AdminPage.css";

function AdminPage() {
  const navigate = useNavigate();
  const [activeTab, setActiveTab] = useState("dashboard");

  const [totalSlots, setTotalSlots] = useState(10);
  const [bookings, setBookings] = useState([]);
  const [facilities, setFacilities] = useState([]);
  const [analytics, setAnalytics] = useState([]);
  const [users, setUsers] = useState([]);

  const [loadingBookings, setLoadingBookings] = useState(true);
  const [loadingFacilities, setLoadingFacilities] = useState(true);
  const [loadingAnalytics, setLoadingAnalytics] = useState(true);
  const [loadingUsers, setLoadingUsers] = useState(true);

  const [newFacility, setNewFacility] = useState({
    facilityName: "",
    address: "",
    city: "",
    state: "",
    zipCode: "",
    totalSlots: "",
    contactInfo: ""
  });

  const [searchTerm, setSearchTerm] = useState("");

  useEffect(() => {
    fetchBookings();
    fetchFacilities();
    fetchAnalytics();
    fetchUsers();
  }, []);

  const fetchBookings = () => {
    fetch("http://localhost:8081/api/bookings")
      .then((res) => res.json())
      .then((data) => {
        setBookings(data);
        setLoadingBookings(false);
      })
      .catch(() => setLoadingBookings(false));
  };

  const fetchFacilities = () => {
    fetch("http://localhost:8081/facilities")
      .then((res) => res.json())
      .then((data) => {
        setFacilities(data);
        setLoadingFacilities(false);
      })
      .catch(() => setLoadingFacilities(false));
  };

  const fetchAnalytics = () => {
    fetch("http://localhost:8081/facility-analytics")
      .then((res) => res.json())
      .then((data) => {
        setAnalytics(data);
        setLoadingAnalytics(false);
      })
      .catch(() => setLoadingAnalytics(false));
  };

  const fetchUsers = () => {
    fetch("http://localhost:8081/api/users")
      .then((res) => res.json())
      .then((data) => {
        setUsers(data);
        setLoadingUsers(false);
      })
      .catch(() => setLoadingUsers(false));
  };

  const handleLogout = () => {
    localStorage.clear();
    navigate("/admin-login");
  };

  const handleFacilityChange = (e) => {
    setNewFacility({ ...newFacility, [e.target.name]: e.target.value });
  };

  const handleAddFacility = (e) => {
    e.preventDefault();

    const facilityToSend = {
      ...newFacility,
      managerId: 1,
      totalSlots: Number(newFacility.totalSlots)
    };

    fetch("http://localhost:8081/facilities", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(facilityToSend)
    })
      .then((res) => res.json())
      .then(() => {
        fetchFacilities();
        setNewFacility({
          facilityName: "",
          address: "",
          city: "",
          state: "",
          zipCode: "",
          totalSlots: "",
          contactInfo: ""
        });
      })
      .catch((err) => console.error("Error adding facility:", err));
  };

  const handleDeleteFacility = (facilityId) => {
    if (window.confirm("Are you sure you want to delete this facility?")) {
      fetch(`http://localhost:8081/facilities/${facilityId}`, {
        method: "DELETE"
      })
        .then((res) => {
          if (res.ok) {
            setFacilities(facilities.filter((f) => f.facilityId !== facilityId));
          } else {
            console.error("Failed to delete facility");
          }
        })
        .catch((err) => console.error("Error deleting facility:", err));
    }
  };

  const renderContent = () => {
    if (activeTab === "dashboard") {
      const availableSlots = totalSlots - bookings.length;
      return (
        <div className="dashboard-content">
          <div className="stat-card">
            <h3>Total Slots</h3>
            <p>{totalSlots}</p>
          </div>
          <div className="stat-card">
            <h3>Available Slots</h3>
            <p>{availableSlots >= 0 ? availableSlots : 0}</p>
          </div>
          <div className="stat-card">
            <h3>Total Bookings</h3>
            <p>{loadingBookings ? "Loading..." : bookings.length}</p>
          </div>
          <div className="stat-card">
            <h3>Total Facilities</h3>
            <p>{loadingFacilities ? "Loading..." : facilities.length}</p>
          </div>
        </div>
      );
    }

    if (activeTab === "bookings") {
      if (loadingBookings) return <p>Loading bookings...</p>;
      if (!bookings.length) return <p>No bookings found.</p>;
      return (
        <div>
          <h2>All Bookings</h2>
          <table>
            <thead>
              <tr>
                <th>Booking ID</th>
                <th>Vehicle</th>
                <th>Start</th>
                <th>End</th>
                <th>Cost</th>
                <th>Status</th>
              </tr>
            </thead>
            <tbody>
              {bookings.map((b) => (
                <tr key={b.bookingId || b.id}>
                  <td>{b.bookingId || b.id}</td>
                  <td>{b.vehicleNumber}</td>
                  <td>{new Date(b.startTime).toLocaleString()}</td>
                  <td>{new Date(b.endTime).toLocaleString()}</td>
                  <td>${b.totalCost}</td>
                  <td>{b.status}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      );
    }

    if (activeTab === "facilities") {
      return (
        <div>
          <h2>Facilities</h2>
          <div className="facility-form">
            <h3>Add New Facility</h3>
            <form onSubmit={handleAddFacility}>
              <input type="text" name="facilityName" placeholder="Name" value={newFacility.facilityName} onChange={handleFacilityChange} required />
              <input type="text" name="address" placeholder="Address" value={newFacility.address} onChange={handleFacilityChange} required />
              <input type="text" name="city" placeholder="City" value={newFacility.city} onChange={handleFacilityChange} required />
              <input type="text" name="state" placeholder="State" value={newFacility.state} onChange={handleFacilityChange} required />
              <input type="text" name="zipCode" placeholder="Zip Code" value={newFacility.zipCode} onChange={handleFacilityChange} required />
              <input type="number" name="totalSlots" placeholder="Slots" value={newFacility.totalSlots} onChange={handleFacilityChange} required />
              <input type="text" name="contactInfo" placeholder="Contact" value={newFacility.contactInfo} onChange={handleFacilityChange} />
              <button type="submit">Add Facility</button>
            </form>
          </div>

          {loadingFacilities ? (
            <p>Loading facilities...</p>
          ) : facilities.length === 0 ? (
            <p>No facilities found.</p>
          ) : (
            <table>
              <thead>
                <tr>
                  <th>Name</th>
                  <th>Address</th>
                  <th>City</th>
                  <th>State</th>
                  <th>Zip Code</th>
                  <th>Slots</th>
                  <th>Contact</th>
                  <th>Actions</th>
                </tr>
              </thead>
              <tbody>
                {facilities.map((f) => (
                  <tr key={f.facilityId}>
                    <td>{f.facilityName}</td>
                    <td>{f.address}</td>
                    <td>{f.city}</td>
                    <td>{f.state}</td>
                    <td>{f.zipCode}</td>
                    <td>{f.totalSlots}</td>
                    <td>{f.contactInfo || "-"}</td>
                    <td>
                      <button className="delete-btn" onClick={() => handleDeleteFacility(f.facilityId)}>Delete</button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}
        </div>
      );
    }

    if (activeTab === "analytics") {
      if (loadingAnalytics) return <p>Loading facility analytics...</p>;
      if (!analytics.length) return <p>No analytics data available.</p>;
      return (
        <div>
          <h2>Facility Analytics</h2>
          <table>
            <thead>
              <tr>
                <th>Analytics ID</th>
                <th>Facility</th>
                <th>Date</th>
                <th>Total Bookings</th>
                <th>Occupancy Rate (%)</th>
                <th>Revenue ($)</th>
                <th>Avg Booking Duration (hrs)</th>
                <th>Peak Hours</th>
                <th>Utilization Score</th>
              </tr>
            </thead>
            <tbody>
              {analytics.map((a) => (
                <tr key={a.analyticsId}>
                  <td>{a.analyticsId}</td>
                  <td>{a.facility.facilityName}</td>
                  <td>{new Date(a.date).toLocaleDateString()}</td>
                  <td>{a.totalBookings}</td>
                  <td>{(a.occupancyRate * 100).toFixed(2)}</td>
                  <td>${a.revenue.toFixed(2)}</td>
                  <td>{a.averageBookingDuration.toFixed(2)}</td>
                  <td>{a.peakHours || "-"}</td>
                  <td>{a.utilizationScore.toFixed(2)}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      );
    }

    if (activeTab === "users") {
      if (loadingUsers) return <p>Loading users...</p>;
      if (!users.length) return <p>No users found.</p>;

      const filteredUsers = users.filter(
        (u) =>
          u.username.toLowerCase().includes(searchTerm.toLowerCase()) ||
          u.email.toLowerCase().includes(searchTerm.toLowerCase())
      );

      return (
        <div>
          <h2>Users</h2>
          <input
            type="text"
            placeholder="Search by username or email..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
          <table>
            <thead>
              <tr>
                <th>User ID</th>
                <th>Username</th>
                <th>Email</th>
                <th>Role</th>
              </tr>
            </thead>
            <tbody>
              {filteredUsers.map((u) => (
                <tr key={u.userId}>
                  <td>{u.userId}</td>
                  <td>{u.username}</td>
                  <td>{u.email}</td>
                  <td>{u.role}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      );
    }
  };

  return (
    <div className="admin-dashboard">
      <div className="sidebar">
        <h2>Admin Panel</h2>
        <ul>
          <li onClick={() => setActiveTab("dashboard")}>Dashboard</li>
          <li onClick={() => setActiveTab("bookings")}>View Bookings</li>
          <li onClick={() => setActiveTab("facilities")}>Facilities</li>
          <li onClick={() => setActiveTab("analytics")}>Facility Analytics</li>
          <li onClick={() => setActiveTab("users")}>Users</li> {/* New Tab */}
        </ul>
      </div>

      <div className="main-content">
        <div className="topbar">
          <h1>{activeTab.charAt(0).toUpperCase() + activeTab.slice(1)}</h1>
          <button onClick={handleLogout}>Logout</button>
        </div>
        <div className="content-area">{renderContent()}</div>
      </div>
    </div>
  );
}

export default AdminPage;
